{
  "$schema": "https://opencode.ai/config.json",
  "provider": {
    "opencode": {
      "options": {
        "timeout": false
      }
    }
  },
  "agent": {
    "eval_light": {
      "description": "Promptfoo eval agent for light-cost scenarios.",
      "mode": "primary",
      "model": "opencode-go/minimax-m2.7",
      "temperature": 0.1,
      "steps": 60,
      "permission": {
        "read": "allow",
        "write": "allow",
        "edit": "allow",
        "bash": "allow",
        "grep": "allow",
        "glob": "allow",
        "list": "allow",
        "webfetch": "deny"
      }
    },
    "eval_standard": {
      "description": "Promptfoo eval agent for standard scenarios.",
      "mode": "primary",
      "model": "opencode-go/minimax-m2.7",
      "temperature": 0.1,
      "steps": 100,
      "permission": {
        "read": "allow",
        "write": "allow",
        "edit": "allow",
        "bash": "allow",
        "grep": "allow",
        "glob": "allow",
        "list": "allow",
        "webfetch": "deny"
      }
    },
    "eval_high": {
      "description": "Promptfoo eval agent for high-cost scenarios.",
      "mode": "primary",
      "model": "opencode-go/minimax-m2.7",
      "temperature": 0.1,
      "steps": 120,
      "permission": {
        "read": "allow",
        "write": "allow",
        "edit": "allow",
        "bash": "allow",
        "grep": "allow",
        "glob": "allow",
        "list": "allow",
        "webfetch": "deny"
      }
    },
    "eval_x_high": {
      "description": "Promptfoo eval agent for extra-high-cost scenarios.",
      "mode": "primary",
      "model": "opencode-go/minimax-m2.7",
      "temperature": 0.1,
      "steps": 200,
      "permission": {
        "read": "allow",
        "write": "allow",
        "edit": "allow",
        "bash": "allow",
        "grep": "allow",
        "glob": "allow",
        "list": "allow",
        "webfetch": "deny"
      }
    }
  }
}

{
  "name": "@your-org/evals",
  "private": true,
  "description": "Promptfoo eval suite for this repo.",
  "scripts": {
    "eval:smoke": "ad-evals smoke",
    "eval:regression": "ad-evals regression",
    "eval:harness-smoke": "ad-evals run packages/harness-smoke/promptfooconfig.json",
    "test": "node --test scripts/*.test.js",
    "doctor": "ad-evals doctor",
    "view": "ad-evals view"
  },
  "dependencies": {
    "@accelerate-data/promptfoo-eval-harness": "^0.1.0",
    "js-yaml": "^4.1.1",
    "promptfoo": "0.121.9"
  }
}
